import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Quote: simplest case and single main items -------------------------
  it("empty item list → premium 5 G (only the processing fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });

    expect(result).toEqual({ results: [{ premium: 5 }] });
  });
  it("plain sword (base 100 G) for a newcomer → premium 115 G (100 + 10 first insurance + 5 fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("plain amulet (base 60 G) for a newcomer → premium 71 G (60 + 6 first insurance + 5 fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "amulet", material: "silver", enchantment: 2, cursed: false }],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 71 }] });
  });
  it("plain staff (base 80 G) for a newcomer → premium 93 G (80 + 8 first insurance + 5 fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "staff", material: "oak", enchantment: 1, cursed: false }],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 93 }] });
  });
  it.todo("plain potion (base 40 G) for a newcomer → premium 49 G (40 + 4 first insurance + 5 fee)");

  // --- Components and blocks of 3 alike -----------------------------------
  it.todo("1 rune → 25 G base premium");
  it.todo("2 runes → 50 G base premium");
  it.todo("3 runes → 60 G base premium (block applies)");
  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
  it.todo("7 runes → 175 G base premium");
  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");

  // --- Item-specific modifiers --------------------------------------------
  it.todo("cursed sword adds a 50 % surcharge on that item's base premium (100 → 150)");
  it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies (100 → 130)");
  it.todo("sword with enchantment 4 → no high-enchantment surcharge (100 → 100)");
  it.todo("cursed sword with exactly enchantment 5 → both surcharges apply (100 → 180)");

  // --- Policy-wide modifiers ----------------------------------------------
  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
  it.todo("customer with 1 year with MHPCO → no loyalty discount");
  it.todo("each item in a quote carries a 10 % first insurance surcharge regardless of customer history");
  it.todo("second quote in a scenario receives a 15 % follow-up contract discount");

  // --- Modifier scope on multi-item policies ------------------------------
  it.todo("cursed sword + plain amulet → policy base 160 G, curse adds 50 G (only the sword's base) → 210 G before further modifiers and fee");

  // --- Rounding in the MHPCO's favour --------------------------------------
  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
  it.todo("intermediate amounts are kept as fractions; only the final amount is rounded");

  // --- Integration examples ------------------------------------------------
  it.todo("newcomer with a cursed sword (steel, enchantment 3) → premium 165 G");
  it.todo("3-year customer's second quote, cursed sword enchantment 7 → premium 160 G");

  // --- Insurance sum and cap ----------------------------------------------
  it.todo("policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("policy covering two swords → insurance sum 2000 G, cap 4000 G");
  it.todo("policy covering a sword and 3 runes → insurance sum 1750 G (block affects premium only), cap 3500 G");
  it.todo("cursed sword (premium 165 G) → cap 2000 G, based on the unmodified insurance value");

  // --- Claim: standard reimbursement ---------------------------------------
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
  it.todo("damage to a rune (no enchantment, no material), damage 200 G → payout 100 G");

  // --- Claim: special clauses ----------------------------------------------
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % then deductible)");
  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins, then deductible)");
  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");

  // --- Claim: deductible per damage event ----------------------------------
  it.todo("dragon attack damages sword (500 G) and amulet (300 G) → payout 600 G (deductible once per damaged item)");
  it.todo("dragon attack damages both of two insured swords → each damage entry gets its own deductible");
  it.todo("damage amount below the deductible does not produce a negative payout");

  // --- Claim: cap ----------------------------------------------------------
  it.todo("sword policy (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
  it.todo("sword policy, second successive claim of 1500 G → payout 600 G, remainingCap 0 G (reduced to remaining cap)");

  // --- Error cases ---------------------------------------------------------
  it.todo("quote with an unknown item type (broomstick) → error");
  it.todo("claim referencing an item not part of the policy (amulet when only a sword is insured) → error");
  it.todo("claim referencing an item with an unknown type → error");
  it.todo("claim with more damage entries of a type than the policy covers (two sword damages, one sword insured) → error");
  it.todo("claim with a damage entry of amount -200 → error");

  // --- CLI -----------------------------------------------------------------
  it.todo("CLI reads a scenario from stdin and writes {results: [...]} to stdout in step order");
  it.todo("CLI on the schema example → results [{premium: ...}, {payout: 100, remainingCap: ...}]");
  it.todo("CLI exits with a non-zero status code and writes an error to stderr for an unknown item type, with no results on stdout");
  it.todo("CLI exits with a non-zero status code and writes an error to stderr for an invalid claim");
});

