export interface Customer {
  yearsWithMHPCO: number;
}

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export type Step = QuoteStep;

export interface QuoteResult {
  premium: number;
}

export type StepResult = QuoteResult;

export interface ScenarioResult {
  results: StepResult[];
}

const PROCESSING_FEE = 5;

const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};

const itemBasePremium = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];

const quotePremium = (step: QuoteStep): number => {
  const policyBasePremium = step.items.reduce(
    (sum, item) => sum + itemBasePremium(item),
    0,
  );
  const firstInsuranceSurcharge =
    policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  return policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE;
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
});

