export interface Customer {
  yearsWithMHPCO: number;
}

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export type Step = QuoteStep;

export interface QuoteResult {
  premium: number;
}

export type StepResult = QuoteResult;

export interface ScenarioResult {
  results: StepResult[];
}

const sumBy = <T>(values: T[], amount: (value: T) => number): number =>
  values.reduce((total, value) => total + amount(value), 0);

const PROCESSING_FEE = 5;

const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const itemBasePremium = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];

const BLOCK_SIZE = 3;

const BLOCK_BASE_PREMIUM = 60;

const basePremiumForSameTypeItems = (items: Item[]): number =>
  items.length === BLOCK_SIZE
    ? BLOCK_BASE_PREMIUM
    : sumBy(items, itemBasePremium);

const sameTypeGroups = (items: Item[]): Item[][] => {
  const groupsByType = new Map<string, Item[]>();
  for (const item of items) {
    const group = groupsByType.get(item.type) ?? [];
    group.push(item);
    groupsByType.set(item.type, group);
  }
  return [...groupsByType.values()];
};

const quotePremium = (step: QuoteStep): number => {
  const policyBasePremium = sumBy(
    sameTypeGroups(step.items),
    basePremiumForSameTypeItems,
  );
  const firstInsuranceSurcharge =
    policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  return policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE;
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
});

