const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

const insuranceValue = (item: Item): number =>
  INSURANCE_VALUE_BY_TYPE[item.type];

// The block discount affects the premium only, never the insurance sum.
const insuranceSum = (policy: QuoteStep): number =>
  sumBy(policy.items, insuranceValue);

const DEDUCTIBLE = 100;

const CAP_MULTIPLE = 2;

const claimResult = (step: ClaimStep, policy: QuoteStep): ClaimResult => {
  const payout = sumBy(
    step.incident.damages,
    (damage) => damage.amount - DEDUCTIBLE,
  );
  const cap = insuranceSum(policy) * CAP_MULTIPLE;
  return { payout, remainingCap: cap - payout };
};

// A step's index is exactly the number of contracts concluded before it.
export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step, precedingContracts) =>
    step.op === "claim"
      ? claimResult(step, scenario.steps[step.policy] as QuoteStep)
      : {
          premium: quotePremium(step, scenario.customer, precedingContracts),
        },
  ),
});

