    reimbursementForDamage(damage, insuredItemFor(damage, policy)),
  );
  const payout = Math.min(reimbursement, capRemaining);
  return { payout, remainingCap: capRemaining - payout };
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const results: StepResult[] = [];
  const capRemainingByPolicy = new Map<number, number>();
  let concludedContracts = 0;
  for (const step of scenario.steps) {
    if (step.op === "claim") {
      const policy = scenario.steps[step.policy] as QuoteStep;
      const capRemaining =
        capRemainingByPolicy.get(step.policy) ?? policyCap(policy);
      const result = settleClaim(step, policy, capRemaining);
      capRemainingByPolicy.set(step.policy, result.remainingCap);
      results.push(result);
    } else {
      results.push({
        premium: quotePremium(step, scenario.customer, concludedContracts),
      });
      concludedContracts += 1;
    }
  }
  return { results };
};

