  FIRST_INSURANCE_SURCHARGE_RATE +
  loyaltyDiscountRate(customer) +
  followUpContractDiscountRate(precedingContracts);

const quotePremium = (
  step: QuoteStep,
  customer: Customer,
  precedingContracts: number,
