cat > /tmp/probe.mjs <<'EOF'
const BASE = { sword:100, amulet:60, staff:80, potion:40, rune:25, moonstone:25 };
const types = Object.keys(BASE);

// exact: ceil(base + surcharges + base*modRate + 5)
// naive: ceil(base + round-each(surcharges) + round(base*modRate) + 5) using ceil on each positive term, floor... 
// Model "rounding intermediates" as ceil() applied to each fractional term (MHPCO's favour).
const found = [];
for (const t of types) {
  for (let n = 1; n <= 4; n++) {
    for (const cursed of [false, true]) {
      for (const ench of [0,3,5,7,9]) {
        for (const years of [0,2]) {
          for (const preceding of [0,1]) {
            const items = Array.from({length:n}, () => ({type:t, cursed, enchantment:ench}));
            // policy base with block rule
            const base = n === 3 ? 60 : n * BASE[t];
            const rate = (cursed?0.5:0) + (ench>=5?0.3:0);
            const surch = n * BASE[t] * rate; // per item, on unmodified item base
            const modRate = 0.1 + (years>=2?-0.2:0) + (preceding>0?-0.15:0);
            const mod = base * modRate;
            const exact = Math.ceil(base + surch + mod + 5);
            const naive = Math.ceil(base + Math.ceil(surch) + Math.ceil(mod) + 5);
            if (exact !== naive) found.push({t,n,cursed,ench,years,preceding,exact,naive,surch,mod});
          }
        }
      }
    }
  }
}
console.log("discriminating cases:", found.length);
console.log(found.slice(0,8));
