const BASE = { sword:100, amulet:60, staff:80, potion:40, rune:25, moonstone:25 };
const types = Object.keys(BASE);
const isFrac = (x) => Math.abs(x - Math.round(x)) > 1e-9;
const found = [];
for (const t of types) {
  for (let n = 1; n <= 7; n++) {
    for (const cursed of [false, true]) {
      for (const ench of [0,3,5,7,9]) {
        for (const years of [0,2]) {
          for (const preceding of [0,1]) {
            const base = n === 3 ? 60 : n * BASE[t];
            const rate = (cursed?0.5:0) + (ench>=5?0.3:0);
            const surch = n * BASE[t] * rate;
            const modRate = 0.1 + (years>=2?-0.2:0) + (preceding>0?-0.15:0);
            const mod = base * modRate;
            // require a genuinely fractional intermediate AND a whole-ish total mismatch
            if (!isFrac(surch) && !isFrac(mod)) continue;
            const exactTotal = base + surch + mod + 5;
            const exact = Math.ceil(Math.round(exactTotal*1e6)/1e6);
            const naive = Math.ceil(base + Math.ceil(surch-1e-9) + Math.ceil(mod-1e-9) + 5);
            if (exact !== naive) found.push({t,n,cursed,ench,years,preceding,surch,mod,exactTotal,exact,naive});
          }
        }
      }
    }
  }
}
console.log("count:", found.length);
for (const f of found.slice(0,6)) console.log(JSON.stringify(f));
